  name                      = "example_resource"
  blocked_input_messaging   = "Blocked"
  blocked_outputs_messaging = "Blocked"

  content_policy_config {
    filters_config {
      type            = "HATE"          # Critical: configures content filtering
      input_strength  = "HIGH"
      output_strength = "HIGH"
    }
  }
}
